var tape=require("tape"),protobuf=require(".."),def={oneof:["a","b"],options:{}},proto='syntax = "proto3";message Test {    oneof kind {        uint32 a = 1;        string b = 2;    }    bool c = 3;}';tape.test("reflected oneofs",function(e){var o=protobuf.OneOf.fromJSON("kind",{oneof:["a","b"],options:{}});e.same(o.toJSON(),def,"should construct from and convert back to JSON");var t=protobuf.parse(proto).root,a=t.lookup("Test"),d=a.get("kind"),r=a.get("c");d.add(r),e.same(d.toJSON(),{oneof:["a","b","c"]},"should allow adding fields"),e.ok(a.get("c"),"should still have the field on the parent"),d.remove(r),e.same(d.toJSON(),{oneof:["a","b"]},"should allow removing fields"),e.ok(a.get("c"),"should still have the field on the parent");var n=new protobuf.Type("Test2");t.add(n),n.add(r),d.add(r),e.notOk(n.get("c"),"should remove the field from the previous parent");var s=new protobuf.Field("d",4,"float");d.add(s),a.remove(s),a.remove(d),e.same(a.fields,{},"should remove all fields from the parent"),e.same(d.oneof,["a","b","c","d"],"should still have the fields on the oneof"),e.end()});